-- The Rogue (local/player_model/rogue, a UE5-skeleton Maya scene) as the other player's body. No cooked asset: one
-- ProceduralMeshComponent per bone (geometry in survivor_mesh.lua, generated by tools/model/body_mesh_data.py), attached to the
-- remote character's CharacterMesh0 at that bone, so the game's replicated ALS animation drives it. The mannequin stays invisible.
-- VARIANTS: the host's body and the guest's body differ (colours, parts), so each player looks unlike the other.
-- Part placement: REF is the mannequin's reference pose (component space, cm, rotation as quaternion) read live from an
-- unanimated copy of its mesh. Each part is rotated about its bone origin from the survivor's rest bone direction onto the
-- mannequin's (so arms follow its A-pose), then into the bone's local frame. Never on our own body (session.lua decides).
local common = require("common")
local log = common.log

local M = {}
function M.enabled() return os.getenv("PT_MUTATE") ~= "nosurvivor" end

local REF = {
    pelvis={0.00,-1.06,96.75,0.00129,0.70711,-0.00129,-0.70711},
    spine_01={0.00,-0.17,107.56,-0.04540,-0.70565,0.04540,0.70565},
    spine_02={0.00,-1.52,126.76,-0.04133,0.70590,0.04133,-0.70590},
    spine_03={0.00,-3.50,140.03,0.05844,-0.70469,-0.05844,0.70469},
    neck_01={0.00,-5.88,156.42,0.08634,0.70182,-0.08634,-0.70182},
    head={0.00,-3.98,165.52,0.00815,-0.70706,-0.00815,0.70706},
    clavicle_l={3.78,-2.76,152.20,-0.01949,-0.08265,0.22868,-0.96979},
    upperarm_l={17.70,-9.71,149.53,-0.00264,0.41962,-0.03874,0.90687},
    lowerarm_l={37.26,-11.91,126.45,-0.15391,-0.32959,-0.17923,-0.91409},
    hand_l={56.65,-0.34,111.68,0.67879,0.38914,-0.06954,0.61885},
    middle_01_l={64.49,4.48,103.48,-0.56504,-0.48211,0.21835,-0.63295},
    thigh_l={9.01,-0.53,95.30,-0.05834,-0.74127,-0.04581,0.66710},
    calf_l={13.40,-1.61,52.97,0.07609,0.73787,-0.03618,-0.66966},
    foot_l={17.08,-8.07,13.47,-0.02053,-0.71223,-0.01172,0.70155},
    ball_l={17.91,8.36,2.81,0.52617,0.48050,-0.49594,-0.49629},
    clavicle_r={-3.78,-2.76,152.20,0.96979,0.22868,0.08265,-0.01949},
    upperarm_r={-17.70,-9.71,149.53,-0.90687,-0.03874,-0.41962,-0.00264},
    lowerarm_r={-37.26,-11.91,126.45,0.91409,-0.17923,0.32959,-0.15391},
    hand_r={-56.65,-0.34,111.68,-0.61885,-0.06954,-0.38914,0.67879},
    middle_01_r={-64.49,4.48,103.48,0.63295,0.21835,0.48211,-0.56504},
    thigh_r={-9.01,-0.53,95.30,0.66710,0.04580,-0.74127,0.05834},
    calf_r={-13.40,-1.61,52.97,-0.66966,0.03618,0.73787,-0.07609},
    foot_r={-17.08,-8.07,13.47,0.70155,0.01172,-0.71223,0.02053},
    ball_r={-17.91,8.36,2.81,-0.49629,0.49594,0.48050,-0.52617},
}
-- the bone whose position gives the mannequin's bone direction (ball and head turn like the foot and the neck's tip)
local CHILD = { pelvis = "spine_01", spine_01 = "spine_02", spine_02 = "spine_03", spine_03 = "neck_01", neck_01 = "head",
    clavicle = "upperarm", upperarm = "lowerarm", lowerarm = "hand", hand = "middle_01", thigh = "calf", calf = "foot", foot = "ball" }
local SITTING = { thigh_l = true, thigh_r = true, calf_l = true, calf_r = true, foot_l = true, foot_r = true, ball_l = true, ball_r = true }
-- the part whose placement of the model's joint is where a part starts (survivor_mesh.lua at = the model's joint): neighbouring
-- parts meet in the reference pose although the two skeletons differ (the game's shoulder sits 7 cm higher on the chest, its
-- spine is longer: parts hung straight at the game's joints left gaps at the shoulders and waist, hand play 2026-10-31)
local PARENT = { spine_03 = "pelvis", head = "spine_03", upperarm = "spine_03", lowerarm = "upperarm", hand = "lowerarm",
    thigh = "pelvis", calf = "thigh", foot = "calf", ball = "foot" }

-- [1] the host's body, [2] the guest's: colours by material name (linear RGB) over the model's own, parts left off, and the
-- glowing face on the black mask (survivor_mesh.lua head sections glow1/glow2, tools/model/body_mesh_data.py GLOW) with its colour
local MASK = { 0.004, 0.004, 0.004 }
local VARIANTS = {
    { colors = { Head = MASK }, hide = { glow2 = true }, glow = { 1.0, 0.62, 0.12 } },
    { colors = { Head = MASK, Cloth = { 0.035, 0.05, 0.03 }, LeatherA = { 0.11, 0.115, 0.095 }, LeatherB = { 0.045, 0.04, 0.035 } },
      hide = { glow1 = true }, glow = { 0.3, 1.0, 0.45 } },
}
local GLOW_INTENSITY = 20
-- every colour times this (the model's own colours were too dark in the game's light, hand play 2026-10-31), at most 0.8
local BRIGHT = 2.5
-- whose body this process draws: the host sees the guest's, the guest the host's
local function variant() return VARIANTS[common.netMode() == "listen" and 2 or 1] end

local function valid(o) return type(o) == "userdata" and o:IsValid() and not o:HasAnyInternalFlags(EInternalObjectFlags.PendingKill) end
local function sub(a, b) return { a[1] - b[1], a[2] - b[2], a[3] - b[3] } end
local function unit(a) local l = math.sqrt(a[1] ^ 2 + a[2] ^ 2 + a[3] ^ 2); return { a[1] / l, a[2] / l, a[3] / l } end
local function pos(n) local r = REF[n]; return { r[1], r[2], r[3] } end
local function rotOf(q) -- quaternion x y z w -> rows of the 3x3 matrix (local -> component)
    local x, y, z, w = q[1], q[2], q[3], q[4]
    return { { 1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w) },
             { 2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w) },
             { 2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y) } }
end
local function apply(m, v) return { m[1][1] * v[1] + m[1][2] * v[2] + m[1][3] * v[3], m[2][1] * v[1] + m[2][2] * v[2] + m[2][3] * v[3], m[3][1] * v[1] + m[3][2] * v[2] + m[3][3] * v[3] } end
local function applyT(m, v) return { m[1][1] * v[1] + m[2][1] * v[2] + m[3][1] * v[3], m[1][2] * v[1] + m[2][2] * v[2] + m[3][2] * v[3], m[1][3] * v[1] + m[2][3] * v[2] + m[3][3] * v[3] } end
local function between(a, b) -- shortest rotation taking unit a onto unit b (Rodrigues)
    local k = { a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1] }
    local c = a[1] * b[1] + a[2] * b[2] + a[3] * b[3]
    local K = { { 0, -k[3], k[2] }, { k[3], 0, -k[1] }, { -k[2], k[1], 0 } }
    local r, f = {}, 1 / (1 + c)
    for i = 1, 3 do
        r[i] = {}
        for j = 1, 3 do
            local k2 = K[i][1] * K[1][j] + K[i][2] * K[2][j] + K[i][3] * K[3][j]
            r[i][j] = (i == j and 1 or 0) + K[i][j] + k2 * f
        end
    end
    return r
end

-- per bone: the section arrays as the game wants them (bone-local cm), built once per process
local built
-- Seated pose (the game has no sitting animation): while seated the leg parts are swapped for a hinged copy hanging on the pelvis
-- part: a thigh piece turning about the hip and a shin+foot piece turning about the knee, both about the body's left-right axis.
-- seatRig.hip_l/_r and knee_l/_r = { at = hinge point in the pelvis frame, secs = geometry relative to it }.
local seatRig = {}
local PELVIS = rotOf({ table.unpack(REF.pelvis, 4, 7) })
local function toPelvis(c) return applyT(PELVIS, sub(c, pos("pelvis"))) end
-- degrees at full sit: thighs a little above level, shins 60 degrees forward of vertical, feet under the dash. The car's hip point is
-- only ~35 cm above its floor: shins hanging down went through it (hand play 2026-10-31)
local THIGH_UP, KNEE_BACK = 95, 35
local SIT_TIME = 0.5 -- s for the fold and the unfold
local function build()
    local data = require("survivor_mesh")
    built = {}
    -- place[bone](v): component-space reference pose position of a model point v relative to the part's anchor: turned about
    -- the anchor from the model's bone direction onto the game's, the anchor where the parent part puts it
    local place = {}
    local function get(bone)
        if place[bone] then return place[bone] end
        local b = data.bones[bone]
        local sfx = bone:match("_[lr]$") or ""
        local base = bone:sub(1, #bone - #sfx)
        local dmv
        if base == "head" then dmv = sub(pos("head"), pos("neck_01"))
        elseif base == "ball" then dmv = sub(pos(bone), pos("foot" .. sfx))
        else dmv = sub(pos(CHILD[base] .. sfx), pos(bone)) end
        local rmin = between((base == "ball" and data.bones["foot" .. sfx] or b).dir, unit(dmv))
        local at = pos(bone)
        local par = PARENT[base] and (data.bones[PARENT[base]] and PARENT[base] or PARENT[base] .. sfx)
        if par and data.bones[par] then at = get(par)(sub(b.at, data.bones[par].at)) end
        place[bone] = function(v) local p = apply(rmin, v); return { at[1] + p[1], at[2] + p[2], at[3] + p[3] }, rmin end
        return place[bone]
    end
    for bone, b in pairs(data.bones) do
        local sfx = bone:match("_[lr]$") or ""
        local base = bone:sub(1, #bone - #sfx)
        local rref = rotOf({ table.unpack(REF[bone], 4, 7) })
        local secs = {}
        -- seated legs: the same geometry in the pelvis bone's frame, relative to the hip (thigh) or the knee (shin, foot)
        local hinge = SITTING[bone] and (base == "thigh" and "hip" or "knee") .. sfx
        local h = hinge and toPelvis(pos((base == "thigh" and "thigh" or "calf") .. sfx))
        local T = get(bone)
        for _, s in ipairs(b.sections) do
            local V, N, SV, SN = {}, {}, {}, {}
            for i = 1, #s.v, 3 do
                local c, rmin = T({ s.v[i], s.v[i + 1], s.v[i + 2] })
                local nc = apply(rmin, { s.n[i], s.n[i + 1], s.n[i + 2] })
                local q = applyT(rref, sub(c, pos(bone)))
                local n = applyT(rref, nc)
                V[#V + 1] = { X = q[1], Y = q[2], Z = q[3] }
                N[#N + 1] = { X = n[1], Y = n[2], Z = n[3] }
                if hinge then
                    local pc, m = toPelvis(c), applyT(PELVIS, nc)
                    SV[#SV + 1] = { X = pc[1] - h[1], Y = pc[2] - h[2], Z = pc[3] - h[3] }
                    SN[#SN + 1] = { X = m[1], Y = m[2], Z = m[3] }
                end
            end
            secs[#secs + 1] = { mat = s.mat, part = s.part, v = V, n = N, t = s.t }
            if hinge then
                seatRig[hinge] = seatRig[hinge] or { at = h, secs = {} }
                table.insert(seatRig[hinge].secs, { mat = s.mat, part = s.part, v = SV, n = SN, t = s.t })
            end
        end
        built[bone] = secs
    end
    -- per variant: its colour of each material index
    for _, va in ipairs(VARIANTS) do
        va.rgb = {}
        for i, name in ipairs(data.materials) do
            local c = va.colors[name] or data.colors[i]
            va.rgb[i] = { math.min(0.8, c[1] * BRIGHT), math.min(0.8, c[2] * BRIGHT), math.min(0.8, c[3] * BRIGHT) }
        end
    end
end

local BASE_MATERIALS = { "/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial", "/Engine/EngineMaterials/WorldGridMaterial.WorldGridMaterial" }
local function baseMaterial()
    for _, p in ipairs(BASE_MATERIALS) do
        local m = StaticFindObject(p)
        if not valid(m) then m = LoadAsset(p) end
        if valid(m) then return m end
    end
end

-- the glow: a game neon light material (Glow Color, Glow Intensity, no textures), the garage's lamp if the sign is not there
local GLOW_MATERIALS = { "/Game/Env/Town/Props/Exterior/Signs/MI_GasStation_Light_01.MI_GasStation_Light_01",
    "/Game/Env/Garage/MI_Garage_HangingLight_01.MI_Garage_HangingLight_01" }
local function glowMaterial()
    for _, p in ipairs(GLOW_MATERIALS) do
        local m = StaticFindObject(p)
        if not valid(m) then pcall(function() m = LoadAsset(p) end) end
        if valid(m) then return m end
    end
end

local bodies = {} -- character full name -> { char = ..., comps = { bone = component } }
local ID = { Rotation = { X = 0, Y = 0, Z = 0, W = 1 }, Translation = { X = 0, Y = 0, Z = 0 }, Scale3D = { X = 1, Y = 1, Z = 1 } }

-- one part: a procedural mesh on the parent (the character's mesh at a bone, or another part), the variant's sections on it
local function attach(char, parent, socket, secs, base, va)
    local cls = StaticFindObject("/Script/ProceduralMeshComponent.ProceduralMeshComponent")
    local comp = char:AddComponentByClass(cls, false, ID, false)
    if not valid(comp) then return nil end
    comp:K2_AttachToComponent(parent, FName(socket), 2, 2, 2, false)
    comp:SetCollisionEnabled(0)
    comp:SetCastShadow(false)
    local i = 0
    for _, s in ipairs(secs) do
        if not va.hide[s.part] then
            local c = va.rgb[s.mat]
            comp:CreateMeshSection_LinearColor(i, s.v, s.t, s.n, {}, {}, {}, {}, {}, {}, false)
            local glow = s.mat == 0 and glowMaterial()
            if glow then
                local mid = comp:CreateDynamicMaterialInstance(i, glow, FName("PTSurvivorGlow"))
                if valid(mid) then
                    mid:SetVectorParameterValue(FName("Glow Color"), { R = va.glow[1], G = va.glow[2], B = va.glow[3], A = 1 })
                    mid:SetScalarParameterValue(FName("Glow Intensity"), GLOW_INTENSITY)
                end
            elseif s.mat == 0 then
                comp:SetMeshSectionVisible(i, false) -- no neon material in memory: no face rather than a grey one
            elseif base then
                local mid = comp:CreateDynamicMaterialInstance(i, base, FName("PTSurvivor" .. s.mat))
                if valid(mid) then mid:SetVectorParameterValue(FName("Color"), { R = c[1], G = c[2], B = c[3], A = 1 }) end
            end
            i = i + 1
        end
    end
    return comp
end

-- the hinged seated legs on the pelvis part (hidden until M.sit); b.rig = { hip_l = comp, knee_l = comp, ... }
local function attachRig(char, b, base, va)
    b.rig = {}
    for _, sfx in ipairs({ "_l", "_r" }) do
        local hip, knee = seatRig["hip" .. sfx], seatRig["knee" .. sfx]
        local th = hip and attach(char, b.comps.pelvis, "None", hip.secs, base, va)
        local sh = th and knee and attach(char, th, "None", knee.secs, base, va)
        if sh then
            b.rig["hip" .. sfx], b.rig["knee" .. sfx] = th, sh
            th:SetVisibility(false, true)
        end
    end
end

local function destroy(b)
    for _, c in pairs(b.rig or {}) do if valid(c) then c:DestroyComponent() end end
    for _, c in pairs(b.comps) do if valid(c) then c:DestroyComponent() end end
end

-- in a car seat: attached to the car (the host driving is attached by the game, a seated guest by car.lua); M.set checks it every
-- refresh (session.lua, 2 s) because nothing told the guest's side that the host sat down (its legs stood through the floor)
local function inCar(char)
    local ok, p = pcall(function() return char:GetAttachParentActor() end)
    return ok and valid(p) and p:GetClass():GetFName():ToString() == "BP_PlayerCarNew_C"
end

-- Gives (remote = true) or takes away the survivor parts of one character; true when the parts are on it.
function M.set(char, remote)
    if not M.enabled() then return false end
    local key = char:GetFullName()
    local b = bodies[key]
    if b and not valid(b.char) then bodies[key], b = nil, nil end
    if not remote then
        if b then
            destroy(b)
            bodies[key] = nil
        end
        return false
    end
    if b then
        for _, c in pairs(b.comps) do if not valid(c) then bodies[key], b = nil, nil; break end end
        if b then M.sit(char, inCar(char)); return true end
    end
    if not valid(char.Mesh) then return false end
    if not built then
        local ok, err = pcall(build)
        if not ok then log("PT|error survivor build %s", tostring(err)); M.enabled = function() return false end; return false end
    end
    local base, va = baseMaterial(), variant()
    b = { char = char, comps = {}, sit = 0, goal = 0 }
    local n = 0
    for bone, secs in pairs(built) do
        local ok, comp = pcall(attach, char, char.Mesh, bone, secs, base, va)
        if ok and comp then b.comps[bone] = comp; n = n + 1 else log("PT|error survivor part %s %s", bone, tostring(comp)) end
    end
    if b.comps.pelvis then
        local ok, err = pcall(attachRig, char, b, base, va)
        if not ok then log("PT|error survivor seat rig %s", tostring(err)) end
    end
    bodies[key] = b
    M.sit(char, inCar(char))
    log("PT|survivor on %s parts=%d variant=%d", key, n, va == VARIANTS[1] and 1 or 2)
    return true
end

-- quaternion turning by deg about the pelvis frame's left-right axis, the sign chosen so a leg hanging down swings forward
local AXIS, SIGN
local function swing(deg)
    if not AXIS then
        AXIS = applyT(PELVIS, { 1, 0, 0 })
        local down, fwd = applyT(PELVIS, { 0, 0, -1 }), applyT(PELVIS, { 0, 1, 0 })
        -- a +90 degree turn takes a vector perpendicular to the axis to axis x vector
        local r = { AXIS[2] * down[3] - AXIS[3] * down[2], AXIS[3] * down[1] - AXIS[1] * down[3], AXIS[1] * down[2] - AXIS[2] * down[1] }
        SIGN = (r[1] * fwd[1] + r[2] * fwd[2] + r[3] * fwd[3]) > 0 and 1 or -1
    end
    local h = math.rad(deg * SIGN) / 2
    return { X = AXIS[1] * math.sin(h), Y = AXIS[2] * math.sin(h), Z = AXIS[3] * math.sin(h), W = math.cos(h) }
end
local function vecOf(a) return { X = a[1], Y = a[2], Z = a[3] } end

-- poses the seated legs at u (0 standing .. 1 seated)
local function pose(b, u)
    u = u * u * (3 - 2 * u)
    for _, sfx in ipairs({ "_l", "_r" }) do
        local th, sh = b.rig["hip" .. sfx], b.rig["knee" .. sfx]
        if valid(th) and valid(sh) then
            local hip, knee = seatRig["hip" .. sfx].at, seatRig["knee" .. sfx].at
            th:K2_SetRelativeTransform({ Rotation = swing(THIGH_UP * u), Translation = vecOf(hip), Scale3D = ID.Scale3D }, false, {}, true)
            sh:K2_SetRelativeTransform({ Rotation = swing(-KNEE_BACK * u), Translation = vecOf(sub(knee, hip)), Scale3D = ID.Scale3D }, false, {}, true)
        end
    end
end

-- standing <-> seated: the bone-hung legs swap with the hinged ones while those are folded (u > 0)
local function show(b, seated)
    for bone, c in pairs(b.comps) do
        if SITTING[bone] and valid(c) then c:SetVisibility(not seated, false) end
    end
    for _, k in ipairs({ "hip_l", "knee_l", "hip_r", "knee_r" }) do
        if valid(b.rig[k]) then b.rig[k]:SetVisibility(seated, false) end
    end
end

local moving = {} -- character full name -> body while its legs fold or unfold
LoopInGameThreadWithDelay(16, function()
    if not next(moving) then return end
    for key, b in pairs(moving) do
        local ok = pcall(function()
            if not valid(b.char) then moving[key] = nil; return end
            local now = os.clock()
            local step = (now - (b.last or now)) / SIT_TIME
            b.last = now
            b.sit = b.goal > b.sit and math.min(b.goal, b.sit + step) or math.max(b.goal, b.sit - step)
            pose(b, b.sit)
            if b.sit == b.goal then
                moving[key] = nil
                if b.sit == 0 then show(b, false) end
            end
        end)
        if not ok then moving[key] = nil end
    end
end)

-- seated (car.lua sitPose; it also hides the mannequin's thigh bones): the legs fold into a sitting pose over SIT_TIME, and back
function M.sit(char, on)
    local b = bodies[char:GetFullName()]
    if not b or not b.rig or b.goal == (on and 1 or 0) then return end
    b.goal = on and 1 or 0
    if on then
        pose(b, b.sit)
        show(b, true)
    end
    b.last = os.clock()
    moving[char:GetFullName()] = b
end

-- for the scenario: the part components of a character by bone
function M.parts(char) local b = bodies[char:GetFullName()]; return b and b.comps or {} end

return M
